import dpbtf2 = require( './index' );


// TESTS //

const AB = new Float64Array( 6 );

dpbtf2( 'row-major', 'upper', 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 'row-major', 'lower', 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 'row-major', 121, 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 'row-major', 122, 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 'column-major', 'upper', 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 'column-major', 'lower', 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 'column-major', 121, 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 'column-major', 122, 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 101, 'upper', 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 101, 'lower', 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 101, 121, 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 101, 122, 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 102, 'upper', 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 102, 'lower', 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 102, 121, 3, 1, AB, 3 ); // $ExpectType number
dpbtf2( 102, 122, 3, 1, AB, 3 ); // $ExpectType number
dpbtf2.ndarray( 'upper', 3, 1, AB, 1, -2, 4 ); // $ExpectType number
dpbtf2.ndarray( 'lower', 3, 1, AB, 1, -2, 4 ); // $ExpectType number
dpbtf2.ndarray( 121, 3, 1, AB, 1, -2, 4 ); // $ExpectType number
dpbtf2.ndarray( 122, 3, 1, AB, 1, -2, 4 ); // $ExpectType number

// Runtime-only geometry cannot be expressed by declared scalar types:
dpbtf2( false, 'lower', 3, 1, AB, 3 ); // $ExpectError
dpbtf2( 'row-major', false, 3, 1, AB, 3 ); // $ExpectError
dpbtf2( 'row-major', 'lower', false, 1, AB, 3 ); // $ExpectError
dpbtf2( 'row-major', 'lower', 3, false, AB, 3 ); // $ExpectError
dpbtf2( 'row-major', 'lower', 3, 1, false, 3 ); // $ExpectError
dpbtf2( 'row-major', 'lower', 3, 1, AB, false ); // $ExpectError
dpbtf2(  ); // $ExpectError
dpbtf2( 'row-major' ); // $ExpectError
dpbtf2( 'row-major', 'lower' ); // $ExpectError
dpbtf2( 'row-major', 'lower', 3 ); // $ExpectError
dpbtf2( 'row-major', 'lower', 3, 1 ); // $ExpectError
dpbtf2( 'row-major', 'lower', 3, 1, AB ); // $ExpectError
dpbtf2( 'row-major', 'lower', 3, 1, AB, 3, 0 ); // $ExpectError

// Runtime-only geometry cannot be expressed by declared scalar types:
dpbtf2.ndarray( false, 3, 1, AB, 1, -2, 4 ); // $ExpectError
dpbtf2.ndarray( 'upper', false, 1, AB, 1, -2, 4 ); // $ExpectError
dpbtf2.ndarray( 'upper', 3, false, AB, 1, -2, 4 ); // $ExpectError
dpbtf2.ndarray( 'upper', 3, 1, false, 1, -2, 4 ); // $ExpectError
dpbtf2.ndarray( 'upper', 3, 1, AB, false, -2, 4 ); // $ExpectError
dpbtf2.ndarray( 'upper', 3, 1, AB, 1, false, 4 ); // $ExpectError
dpbtf2.ndarray( 'upper', 3, 1, AB, 1, -2, false ); // $ExpectError
dpbtf2.ndarray(  ); // $ExpectError
dpbtf2.ndarray( 'upper' ); // $ExpectError
dpbtf2.ndarray( 'upper', 3 ); // $ExpectError
dpbtf2.ndarray( 'upper', 3, 1 ); // $ExpectError
dpbtf2.ndarray( 'upper', 3, 1, AB ); // $ExpectError
dpbtf2.ndarray( 'upper', 3, 1, AB, 1 ); // $ExpectError
dpbtf2.ndarray( 'upper', 3, 1, AB, 1, -2 ); // $ExpectError
dpbtf2.ndarray( 'upper', 3, 1, AB, 1, -2, 4, 0 ); // $ExpectError
dpbtf2( 103, 'upper', 3, 1, AB, 3 ); // $ExpectError
dpbtf2( 'row-major', 'U', 3, 1, AB, 3 ); // $ExpectError
dpbtf2( 'row-major', 123, 3, 1, AB, 3 ); // $ExpectError
dpbtf2( 'row-major', 'upper', 3, 1, new Int32Array( 6 ), 3 ); // $ExpectError
dpbtf2.ndarray( 'L', 3, 1, AB, 1, 2, 0 ); // $ExpectError
dpbtf2.ndarray( 123, 3, 1, AB, 1, 2, 0 ); // $ExpectError
dpbtf2.ndarray( 'upper', 3, 1, new Int32Array( 6 ), 1, 2, 0 ); // $ExpectError
